import { Router, type Request } from 'express';
import { LANG_PREFIX, LANGS, type Lang, type Release } from '../shared/models';
import { releasesFrom } from './api';
import type { Catalog } from './catalog';
import { publicOrigin } from './production';

/**
 * /robots.txt and /sitemap.xml — generated by Express, before Angular (server.ts).
 * The sitemap lists every indexable page in all languages, with hreflang links,
 * so search engines know /ksiazka/x and /en/ksiazka/x are the same book in two versions.
 */
export function seoRouter(catalog: Catalog): Router {
  const router = Router();

  router.get('/robots.txt', (req, res) => {
    const disallow = ['/api/', ...LANGS.map((l) => `${LANG_PREFIX[l]}/moja-polka`)];
    res.type('text/plain').send(
      ['User-agent: *', ...disallow.map((d) => `Disallow: ${d}`), '', `Sitemap: ${origin(req)}/sitemap.xml`, ''].join('\n'),
    );
  });

  // Releases RSS — feed readers and aggregators fetch it periodically, so it is worth caching.
  router.get(LANGS.map((l) => `${LANG_PREFIX[l]}/rss/premiery`), (req, res) => {
    const lang = LANGS.find((l) => LANG_PREFIX[l] && req.path.startsWith(LANG_PREFIX[l])) ?? LANGS[0];
    res.set('Cache-Control', 'public, max-age=3600');
    res.type('application/rss+xml').send(rssXml(catalog.listReleases(releasesFrom(), lang), origin(req), lang));
  });

  router.get('/sitemap.xml', (req, res) => {
    res.type('application/xml').send(sitemapXml(sitemapPaths(catalog), origin(req)));
  });

  return router;
}

/** Paths without the language prefix. Search with filters is skipped — the combinations are endless. */
export function sitemapPaths(catalog: Catalog): string[] {
  const books = catalog.listBooks();
  const authors = [...new Set(books.map((b) => b.author.slug))];
  return [
    '/',
    '/tropy',
    '/szukaj',
    ...catalog.listTropes().map((t) => `/tropy/${t.slug}`),
    ...books.map((b) => `/ksiazka/${b.slug}`),
    ...authors.map((a) => `/autor/${a}`),
  ];
}

export function sitemapXml(paths: string[], origin: string): string {
  const url = (lang: Lang, path: string) => escapeXml(origin + LANG_PREFIX[lang] + path);
  const entries = paths.flatMap((path) =>
    LANGS.map((lang) =>
      [
        '  <url>',
        `    <loc>${url(lang, path)}</loc>`,
        ...LANGS.map((alt) => `    <xhtml:link rel="alternate" hreflang="${alt}" href="${url(alt, path)}"/>`),
        `    <xhtml:link rel="alternate" hreflang="x-default" href="${url(LANGS[0], path)}"/>`,
        '  </url>',
      ].join('\n'),
    ),
  );
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">',
    ...entries,
    '</urlset>',
    '',
  ].join('\n');
}

/**
 * The site's public address. In production set PUBLIC_ORIGIN=https://… (on Render RENDER_EXTERNAL_URL
 * is used): search engines store the sitemap, so we never build it from the Host header a client can forge.
 * Locally (localhost) we take the address from the request, so dev works without configuration.
 */
function origin(req: Request): string {
  const configured = publicOrigin();
  if (configured) return configured;
  return req.hostname === 'localhost' ? `${req.protocol}://${req.get('host')}` : 'http://localhost';
}

/** RSS 2.0. Everything that comes from data goes through escapeXml — a title with "<" cannot break the feed. */
export function rssXml(releases: Release[], origin: string, lang: Lang): string {
  const page = `${origin}${LANG_PREFIX[lang]}/premiery`;
  const title = lang === 'pl' ? 'Łuska i Ciernie — nadchodzące premiery' : 'Łuska i Ciernie — upcoming releases';
  const items = releases.map((r) =>
    [
      '    <item>',
      `      <title>${escapeXml(`${r.title} — ${r.author}`)}</title>`,
      `      <link>${escapeXml(`${page}#${r.slug}`)}</link>`,
      `      <guid isPermaLink="false">premiera-${escapeXml(r.slug)}</guid>`,
      // pubDate = the release day (RFC 822, as RSS 2.0 requires). For a month or quarter it is the
      // period's last day, so the description says the date is approximate.
      `      <pubDate>${new Date(`${r.date}T00:00:00Z`).toUTCString()}</pubDate>`,
      ...(description(r, lang) ? [`      <description>${escapeXml(description(r, lang))}</description>`] : []),
      '    </item>',
    ].join('\n'),
  );
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<rss version="2.0">',
    '  <channel>',
    `    <title>${escapeXml(title)}</title>`,
    `    <link>${escapeXml(page)}</link>`,
    `    <description>${escapeXml(title)}</description>`,
    `    <language>${lang}</language>`,
    ...items,
    '  </channel>',
    '</rss>',
    '',
  ].join('\n');
}

function description(r: Release, lang: Lang): string {
  if (r.precision === 'day') return r.note ?? '';
  const year = r.date.slice(0, 4);
  const when =
    r.precision === 'month'
      ? new Intl.DateTimeFormat(lang, { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${r.date}T00:00:00Z`))
      : `${lang === 'pl' ? ['I', 'II', 'III', 'IV'][Math.ceil(+r.date.slice(5, 7) / 3) - 1] + ' kw.' : 'Q' + Math.ceil(+r.date.slice(5, 7) / 3)} ${year}`;
  const label = lang === 'pl' ? `Termin przybliżony: ${when}` : `Approximate date: ${when}`;
  return r.note ? `${label} · ${r.note}` : label;
}

function escapeXml(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
